# Let's also verify the copied sheets are identical to source
import openpyxl

src_wb = openpyxl.load_workbook('materials/FinancialStatementFY26Q4.xlsx', data_only=False)
new_wb = openpyxl.load_workbook('summary.xlsx', data_only=False)

# Check each sheet (excluding Summary)
for sheet_name in src_wb.sheetnames:
    src_ws = src_wb[sheet_name]
    new_ws = new_wb[sheet_name]

    # Check dimensions
    if src_ws.dimensions != new_ws.dimensions:
        print(f"MISMATCH in {sheet_name}: dimensions {src_ws.dimensions} vs {new_ws.dimensions}")
        continue

    # Check a sample of cells
    mismatches = 0
    for row in src_ws.iter_rows():
        for cell in row:
            new_cell = new_ws.cell(row=cell.row, column=cell.column)
            if cell.value != new_cell.value:
                mismatches += 1
                if mismatches <= 3:
                    print(f"MISMATCH in {sheet_name} {cell.coordinate}: {cell.value!r} vs {new_cell.value!r}")

    if mismatches == 0:
        print(f"{sheet_name}: OK (all cells match)")
    else:
        print(f"{sheet_name}: {mismatches} mismatches found")

print()
print("Total sheets:", len(new_wb.sheetnames))
print("Summary sheet exists:", 'Summary' in new_wb.sheetnames)
